  // No href, "", "#" and javascript: go nowhere, so a click on them pins
  // the element as on any other (agents' mocks use <a href="#"> for buttons).
  function isFollowableHref(raw) {
    return !!raw && raw !== '#' && !/^javascript:/i.test(raw);
  }

